iterate.script:
problem = null
for (const [field, verbNoun] of Object.entries(contracts)) {
    const serviceName = row[field]
    if (!serviceName) continue
    const definition = ec.service.getServiceDefinition(serviceName)
    if (!definition) {
        problem = "names a missing service " + serviceName
        break
    }
    const declared = Array.from(definition.inParameterNames || [])
    const required = Array.from(ec.service.getServiceDefinition("org.moqui.maps.MapServices." + verbNoun).inParameterNames || [])
    const lacking = required.filter(name => !declared.includes(name))
    if (lacking.length) {
        problem = "names " + serviceName + ", which does not implement " + verbNoun + " (no " + lacking.join(", ") + ")"
        break
    }
}
if (!problem && !row.contextServiceName && !row.featuresServiceName) problem = "names no context or features service"
